import { ReactNode, FC } from 'react';

type PopoverPlacement = 'top' | 'top-start' | 'top-end' | 'bottom' | 'bottom-start' | 'bottom-end' | 'left' | 'left-start' | 'left-end' | 'right' | 'right-start' | 'right-end';
type PopoverTrigger = 'click' | 'manual';
interface PopoverAction {
    /** 选项文字 */
    text: string;
    /** 选项图标 */
    icon?: ReactNode;
    /** 是否禁用 */
    disabled?: boolean;
    /** 自定义颜色 */
    color?: string;
}
interface PopoverProps {
    /** 是否打开 (受控) */
    open?: boolean;
    /** 默认是否打开 (非受控) */
    defaultOpen?: boolean;
    /** 打开状态变化 */
    onOpenChange?: (open: boolean) => void;
    /** 选项列表 */
    actions?: PopoverAction[];
    /** 选项点击 */
    onSelect?: (action: PopoverAction, index: number) => void;
    /** 弹出位置 */
    placement?: PopoverPlacement;
    /** 触发方式 */
    trigger?: PopoverTrigger;
    /** 触发元素 */
    children: ReactNode;
    /** 自定义内容 (优先级高于 actions) */
    content?: ReactNode;
    /** 是否显示遮罩 */
    overlay?: boolean;
    /** 点击遮罩关闭 */
    closeOnOverlayClick?: boolean;
    /** 点击选项后关闭 */
    closeOnSelect?: boolean;
    /** 主题 */
    theme?: 'light' | 'dark';
    /** 偏移量 [水平, 垂直] */
    offset?: [number, number];
    /** 自定义类名 */
    className?: string;
}

declare const Popover: FC<PopoverProps>;

export { Popover, Popover as default };
export type { PopoverAction, PopoverPlacement, PopoverProps, PopoverTrigger };
